#pragma once

// Thin host-side wrapper around the Metal kernels. Everything here takes and
// returns plain arrays laid out exactly as the kernels expect; the physics and
// the bookkeeping live in gravity_backends.h. On builds without Metal the
// functions exist but throw.

#include <memory>
#include <string>
#include <vector>

#include "galactic_tides/kernels/gravity_kernels.h"

namespace galactic_tides {
namespace metal {

// The Metal source (gravity_kernels.h + gravity_kernels.metal) compiled at
// run time; generated by CMake on every platform.
extern const char *const kKernelSource;

// True if built with Metal support (does not check for a device).
bool compiled_in();

class Context {
 public:
  Context();  // throws if Metal is unavailable or the kernels fail to compile
  ~Context();
  Context(const Context &) = delete;
  Context &operator=(const Context &) = delete;

  std::string device_name() const;

  // out[i] = (ax, ay, az, potential) for every body against every other.
  void direct(const std::vector<kern::float4> &bodies, const kern::GTParams &p,
              std::vector<kern::float4> &out);

  // Evaluates grouped interaction lists: out[i] for every body i in tree
  // order. p.n and p.n_groups must match the arrays; threads_per_group must
  // be at least the largest group.
  void tree(const std::vector<kern::float4> &bodies, const std::vector<kern::GTCell> &cells,
            const std::vector<kern::uint> &cell_list, const std::vector<kern::GTRange> &leaf_list,
            const std::vector<kern::GTGroup> &groups, const kern::GTParams &p,
            unsigned threads_per_group, std::vector<kern::float4> &out);

 private:
  struct Impl;
  std::unique_ptr<Impl> impl_;
};

}  // namespace metal
}  // namespace galactic_tides
